void aacTablesInit(AacTables *tables)
{
	int32_t i;

	tables->bitReverse = bitReverse;
	tables->samplingRates = samplingRates;
	tables->swbOffsetLong[0] = swbOffsetLong96;
	tables->swbOffsetLong[1] = swbOffsetLong96;
	tables->swbOffsetLong[2] = swbOffsetLong64;
	tables->swbOffsetLong[3] = swbOffsetLong48;
	tables->swbOffsetLong[4] = swbOffsetLong48;
	tables->swbOffsetLong[5] = swbOffsetLong32;
	tables->swbOffsetLong[6] = swbOffsetLong24;
	tables->swbOffsetLong[7] = swbOffsetLong24;
	tables->swbOffsetLong[8] = swbOffsetLong16;
	tables->swbOffsetLong[9] = swbOffsetLong16;
	tables->swbOffsetLong[10] = swbOffsetLong16;
	tables->swbOffsetLong[11] = swbOffsetLong8;
	tables->swbOffsetShort[0] = swbOffsetShort96;
	tables->swbOffsetShort[1] = swbOffsetShort96;
	tables->swbOffsetShort[2] = swbOffsetShort64;
	tables->swbOffsetShort[3] = swbOffsetShort48;
	tables->swbOffsetShort[4] = swbOffsetShort48;
	tables->swbOffsetShort[5] = swbOffsetShort48;
	tables->swbOffsetShort[6] = swbOffsetShort24;
	tables->swbOffsetShort[7] = swbOffsetShort24;
	tables->swbOffsetShort[8] = swbOffsetShort16;
	tables->swbOffsetShort[9] = swbOffsetShort16;
	tables->swbOffsetShort[10] = swbOffsetShort16;
	tables->swbOffsetShort[11] = swbOffsetShort8;
	tables->numSwb[0] = numSwbLong;
	tables->numSwb[1] = numSwbShort;
	tables->tnsMaxOrder = tnsMaxOrder;
	tables->tnsMaxBands[0] = tnsMaxBandsLong;
	tables->tnsMaxBands[1] = tnsMaxBandsShort;
	tables->predSfbMax = predSfbMax;
	tables->sineWindowLong = sineWindowLong;
	tables->sineWindowShort = sineWindowShort;
	tables->kbdWindowLong = kbdWindowLong;
	tables->kbdWindowShort = kbdWindowShort;
	tables->imdctCosLong = imdctCosLong;
	tables->imdctSinLong = imdctSinLong;
	tables->imdctCosShort = imdctCosShort;
	tables->imdctSinShort = imdctSinShort;
	tables->fftCos = fftCos;
	tables->fftSin = fftSin;
	tables->tnsCoef3 = tnsCoef3;
	tables->tnsCoef4 = tnsCoef4;
	tables->pow2Quarter = pow2Quarter;
	tables->pow2Third = pow2Third;
	tables->pow43Mantissa = pow43Mantissa;
	tables->pow43Exponent = pow43Exponent;
	for (i = 0; i < AAC_CODEBOOKS; i++) {
		tables->codebooks[i].dimension = codebookDimensions[i];
		tables->codebooks[i].lav = codebookLav[i];
		tables->codebooks[i].isUnsigned = codebookUnsigned[i];
	}
	tables->codebooks[0].tree = huffmanTree0;
	tables->codebooks[1].tree = huffmanTree1;
	tables->codebooks[2].tree = huffmanTree2;
	tables->codebooks[3].tree = huffmanTree3;
	tables->codebooks[4].tree = huffmanTree4;
	tables->codebooks[5].tree = huffmanTree5;
	tables->codebooks[6].tree = huffmanTree6;
	tables->codebooks[7].tree = huffmanTree7;
	tables->codebooks[8].tree = huffmanTree8;
	tables->codebooks[9].tree = huffmanTree9;
	tables->codebooks[10].tree = huffmanTree10;
	tables->codebooks[11].tree = huffmanTree11;
}
